def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "slice_apple_in_trash": And([
            self.robot_at(self.trash_bin),
            self.trash_bin_identified,
            Not(self.on_clean_surface(self.apple))
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
